function params(){var g=function(i){return document.getElementById(i);};var which=g("lp-which").value;if(which==="auto")which=side.side==="sell"?"sell":side.side==="buy"?"buy":"both";return{which:which,mid:Number(g("lp-mid").value)||0,amt:Number(g("lp-amt").value)||0,n:Number(g("lp-n").value)||5,sp:Number(g("lp-sp").value)||0,step:Number(g("lp-step").value)||0,dur:Number(g("lp-dur").value)};}
